(function(){
  const clone=o=>JSON.parse(JSON.stringify(o));
  const data=window.ARENA_DATA;
  if(!data || typeof document==="undefined" || !document.querySelector || !document.querySelector("#setup-view")) return;
  const state={view:"setup",setupStep:1,connected:{meta:false,google:false,tiktok:false},tracking:false,analysis:false,launched:false,proposalsApplied:false,creativeSet:"A",filter:"all",cards:clone(data.arenaCardsBefore),summary:data.summaryBefore,drawer:false};
  const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
  const money=n=>`NT$ ${Number(n).toLocaleString("en-US")}`;
  const creativeMap=()=>{const all=[...data.creativeSetA,...data.creativeSetB];return Object.fromEntries(all.map(x=>[x.id,x]));};
  const svgThumb=(seed)=>{const colors={"orange-beans":["#f97316","#7c2d12"],"green-cup":["#22c55e","#14532d"],"blue-search":["#60a5fa","#1e3a8a"],"gold-search":["#fbbf24","#713f12"],"red-pour":["#f87171","#7f1d1d"],"lime-timer":["#a3e635","#365314"],"coral-morning":["#fb7185","#881337"],"teal-box":["#2dd4bf","#134e4a"],"slate-search":["#94a3b8","#334155"],"amber-search":["#f59e0b","#78350f"],"violet-pour":["#c084fc","#581c87"],"yellow-scale":["#fde047","#713f12"]}[seed]||["#f97316","#1f2937"]; const [a,b]=colors; const isSearch=seed.includes("search"); return `<svg viewBox="0 0 320 120" aria-hidden="true"><rect width="320" height="120" fill="${b}"/><circle cx="250" cy="-4" r="78" fill="${a}" opacity=".84"/><path d="M0 92 Q62 45 126 84 T258 62 T360 75 V120 H0Z" fill="${a}" opacity=".7"/>${isSearch?`<rect x="24" y="27" width="150" height="13" rx="6" fill="#fff" opacity=".88"/><rect x="24" y="49" width="200" height="8" rx="4" fill="#fff" opacity=".45"/>`:`<circle cx="${seed.includes("cup")?150:112}" cy="58" r="24" fill="#fff" opacity=".9"/><path d="M${seed.includes("cup")?132:99} 72 Q${seed.includes("cup")?150:112} 91 ${seed.includes("cup")?168:125} 72" fill="none" stroke="${b}" stroke-width="6"/>`}<text x="22" y="103" font-size="12" font-family="Arial" font-weight="700" fill="#fff" opacity=".88">LumiBrew / ${seed.replaceAll("-"," ")}</text></svg>`;};
  function render(){renderView();renderSetup();if(state.view==="arena"){renderSummary();renderBoard();renderProposals();$("#prelaunch-bar").classList.toggle("is-hidden",state.launched);$("#coach-trigger").classList.toggle("is-hidden",!state.launched);}updateProgress();}
  function renderView(){$("#setup-view").classList.toggle("is-hidden",state.view!=="setup");$("#arena-view").classList.toggle("is-hidden",state.view!=="arena");$$('.step-tab').forEach((b,i)=>{b.classList.toggle("is-active",state.view==="setup"&&state.setupStep===i+1);b.disabled=i===1&&!state.analysis;});}
  function renderSetup(){
    $("#setup-step-1").classList.toggle("is-hidden",state.setupStep!==1);$("#setup-step-2").classList.toggle("is-hidden",state.setupStep!==2);
    $("#platform-grid").innerHTML=data.platforms.map(p=>`<article class="platform-card ${state.connected[p.id]?"is-connected":""}"><div class="platform-meta"><div style="display:flex;align-items:center"><span class="platform-logo logo-${p.id}">${p.name[0]}</span><div class="platform-name">${p.name}<span class="platform-caption">廣告帳號</span></div></div><span class="status-pill" style="color:${state.connected[p.id]?"#86efac":"#8b98af"}">${state.connected[p.id]?"已連結":"未連結"}</span></div><button class="connect-button ${state.connected[p.id]?"is-success":""}" data-platform="${p.id}" ${state.connected[p.id]?"disabled":""}>${state.connected[p.id]?"✓ 已連結":"連結"}</button></article>`).join("");
    $("#tracking-result").textContent=state.tracking?"已偵測到追蹤碼 ✓":"";$("#tracking-url").classList.toggle("is-detected",state.tracking);$("#detect-tracking").disabled=state.tracking;$("#detect-tracking").textContent=state.tracking?"已完成":"偵測追蹤碼";
    const ready=Object.values(state.connected).every(Boolean)&&state.tracking;$("#to-strategy").disabled=!ready;$("#setup-hint").textContent=ready?"入場條件完成，可以看策略":"連結三個平台並完成偵測";
    if(state.analysis){$("#analysis-result").classList.remove("is-hidden");$("#analysis-result").innerHTML=analysisMarkup();$("#enter-arena").disabled=false;$("#strategy-hint").textContent="策略已就緒，素材可以上場";}else{$("#analysis-result").classList.add("is-hidden");$("#enter-arena").disabled=true;}
  }
  function analysisMarkup(){const a=data.analysis,s=data.strategy;return `<div class="analysis-cards"><div class="info-card"><h3>賣點</h3><ul>${a.sellingPoints.map(x=>`<li>${x}</li>`).join("")}</ul></div><div class="info-card"><h3>受眾</h3><ul>${a.audiences.map(x=>`<li>${x}</li>`).join("")}</ul></div><div class="info-card"><h3>競品</h3><ul>${a.competitors.map(x=>`<li>${x}</li>`).join("")}</ul></div></div><div class="strategy-card"><div class="strategy-head"><strong>三平台預算分配</strong><span>目標：${s.goal}</span></div><div class="budget-bars"><i style="width:${s.budgetSplit.meta}%"></i><i style="width:${s.budgetSplit.google}%"></i><i style="width:${s.budgetSplit.tiktok}%"></i></div><div class="budget-legend"><span>Meta <b>${s.budgetSplit.meta}%</b></span><span>Google <b>${s.budgetSplit.google}%</b></span><span>TikTok <b>${s.budgetSplit.tiktok}%</b></span></div><div class="strategy-meta"><div><small>投放目標</small><strong>${s.goal}</strong></div><div><small>預估成果區間</small><strong>${s.estimateRange}</strong></div></div></div>`;}
  function updateProgress(){const count=Object.values(state.connected).filter(Boolean).length+(state.tracking?1:0);$("#setup-progress").textContent=`${count}/4`;}
  function renderSummary(){const s=state.summary;$("#summary-strip").innerHTML=`<div class="summary-stat"><small>花費</small><strong>${money(s.spend)}</strong><p>本期已花預算</p></div><div class="summary-stat"><small>訂單數</small><strong>${s.orders} 筆</strong><p>花 ${Math.round(s.spend/s.orders)} 元帶來 1 筆訂單</p></div><div class="summary-stat"><small>每筆成本</small><strong>${money(s.cpa)}</strong><p>平均取得成本</p></div><div class="summary-stat"><small>ROAS</small><strong>${s.roas}x</strong><p>${state.proposalsApplied?"優化後持續上揚":"目前整體回收"}</p></div><div class="trend-tile"><header><span>7 日趨勢</span><strong>${state.proposalsApplied?"尾端上揚":"穩定測試中"}</strong></header>${trendSvg(s.trend7d)}</div>`;}
  function trendSvg(values){const max=Math.max(...values)+.4,min=Math.min(...values)-.2;const pts=values.map((v,i)=>`${(i*100/(values.length-1)).toFixed(1)},${(46-(v-min)/(max-min)*34).toFixed(1)}`).join(" ");return `<svg viewBox="0 0 100 54" preserveAspectRatio="none"><path class="trend-grid" d="M0 12H100M0 29H100M0 46H100"/><polyline class="trend-line" points="${pts}"/>${values.map((v,i)=>{const [x,y]=pts.split(" ")[i].split(",");return `<circle class="trend-dot" cx="${x}" cy="${y}" r="1.8"/>`;}).join("")}</svg>`;}
  function renderBoard(){const cmap=creativeMap(),cols=[{id:"generating",name:"生成中",tone:"idle"},{id:"testing",name:"小額測試中",tone:"testing"},{id:"scaling",name:"勝者放大中",tone:"scaling"},{id:"eliminated",name:"淘汰區",tone:"eliminated"}];$("#arena-board").innerHTML=cols.map(c=>{let cards=state.cards.filter(x=>x.column===c.id).filter(x=>state.filter==="all"||cmap[x.creativeId]?.platform===state.filter);return `<section class="arena-column column-${c.tone}"><div class="column-head"><span class="column-title">${c.name}</span><span class="column-count">${cards.length}</span>${c.id==="generating"?'<button class="column-action" id="refresh-creatives">換一批</button>':''}</div><div class="column-stack">${cards.length?cards.map(x=>cardMarkup(x,cmap[x.creativeId],c.id)).join(""):"<div class=\"empty-state\">目前沒有素材</div>"}</div></section>`;}).join("");}
  function tiktokScriptMarkup(creative){return `<div class="script-panel"><div class="script-heading"><span>短影音腳本</span><small>分鏡時間軸</small></div><ol class="script-timeline">${creative.videoScript.map(scene=>`<li><strong>${scene.time}</strong><span>${scene.visual}</span><em>${scene.audio}</em></li>`).join("")}</ol><p class="cover-description"><strong>封面示意：</strong>${creative.coverDescription}</p></div>`;}
  function cardMarkup(card,creative,column){const stats=card.stats;const show=column==="testing"||column==="scaling";const isTikTok=creative.type==="video_script";return `<article class="creative-card ${column==="scaling"?"is-scaling":""} ${column==="eliminated"?"is-eliminated":""}" data-card="${card.id}"><div class="card-thumb">${svgThumb(creative.thumbnailSvgSeed)}</div><div class="card-topline"><span class="platform-badge ${creative.platform}">${creative.platform}</span><span class="type-badge">${creative.type==="image_text"?"圖文":creative.type==="search_text"?"搜尋":"短影音"}</span></div><h3 class="card-title">${creative.title}</h3><p class="card-copy">${creative.bodyCopy||creative.headline||creative.description}</p>${isTikTok?tiktokScriptMarkup(creative):""}${show?`<div class="card-stats"><div><small>花費</small><strong>${money(stats.spend)}</strong></div><div><small>轉換</small><strong>${stats.orders} 筆</strong></div><div><small>ROAS</small><strong>${stats.roas?stats.roas+"x":"—"}</strong></div></div>`:""}${column==="eliminated"?`<div class="status-stamp">已下架 · ${card.eliminatedReason}</div>`:""}</article>`;}
  function renderProposals(){$("#proposal-count").textContent=state.proposalsApplied?"0":"3";$("#proposal-list").innerHTML=data.proposals.map(p=>`<article class="proposal-card ${state.proposalsApplied?"is-applied":""}"><div class="proposal-top"><span class="proposal-type">${state.proposalsApplied?"已套用 ✓":p.type}</span><span class="type-badge">${p.effect==="replace"?"新挑戰者":"素材戰績"}</span></div><h3>${p.type}這張素材</h3><p>${p.reasonPlain}</p><div class="proposal-impact">預期影響：${p.expectedImpact}</div></article>`).join("");$("#apply-proposals").textContent=state.proposalsApplied?"已全部套用 ✓":"核可優化";$("#apply-proposals").disabled=state.proposalsApplied;}
  function connectPlatform(id){const btn=$(`.connect-button[data-platform="${id}"]`);btn.disabled=true;btn.innerHTML='<span class="spinner" aria-label="載入中"></span>';setTimeout(()=>{state.connected[id]=true;render();},900);}
  function detectTracking(){const btn=$("#detect-tracking");btn.disabled=true;btn.textContent="偵測中…";setTimeout(()=>{state.tracking=true;render();},700);}
  function generateAnalysis(){const btn=$("#generate-analysis");btn.disabled=true;btn.textContent="分析中…";$("#analysis-skeleton").classList.remove("is-hidden");setTimeout(()=>{state.analysis=true;$("#analysis-skeleton").classList.add("is-hidden");render();},900);}
  function swapCreatives(){const board=$("#arena-board");board.style.opacity=".3";setTimeout(()=>{state.creativeSet=state.creativeSet==="A"?"B":"A";const selected=state.creativeSet==="A"?data.creativeSetA:data.creativeSetB;state.cards=selected.map((c,i)=>({id:`card-${c.id}`,creativeId:c.id,column:"generating",stats:{spend:0,orders:0,cpa:0,roas:0},eliminatedReason:""}));board.style.opacity="1";render();},160);}
  function openLaunch(){const s=data.strategy,lc=data.launchConfig;$("#launch-overview").innerHTML=`<div class="overview-item"><small>月預算</small><strong>${money(lc.monthlyBudget)}</strong></div><div class="overview-item"><small>排程</small><strong>${lc.schedule.start} →<br>${lc.schedule.end}</strong></div><div class="overview-item"><small>投放目標</small><strong>${s.goal}</strong></div><div class="overview-item platform-pie"><div class="pie" aria-label="平台分配圓餅圖"></div><div class="budget-legend"><span>Meta <b>${s.budgetSplit.meta}%</b></span><span>Google <b>${s.budgetSplit.google}%</b></span><span>TikTok <b>${s.budgetSplit.tiktok}%</b></span></div></div>`;$("#launch-modal").classList.remove("is-hidden");}
  function confirmLaunch(){ $("#launch-modal").classList.add("is-hidden");showToast("投放啟動中…");setTimeout(()=>{state.launched=true;state.cards=clone(data.arenaCardsBefore).map((card,index)=>({...card,column:"testing",stats:{spend:[420,360,290,180,120,90][index]||120,orders:[2,1,1,0,0,0][index]||0,cpa:[210,360,290,0,0,0][index]||0,roas:[2.4,1.8,1.9,0,0,0][index]||0}}));state.summary=data.summaryBefore;render();},1200);}
  function openCoach(){state.drawer=true;$("#coach-drawer").classList.add("is-open");$("#coach-backdrop").classList.remove("is-hidden");setTimeout(()=>$("#coach-backdrop").classList.add("is-open"),10);}
  function closeCoach(){state.drawer=false;$("#coach-drawer").classList.remove("is-open");$("#coach-backdrop").classList.remove("is-open");setTimeout(()=>$("#coach-backdrop").classList.add("is-hidden"),250);}
  function applyProposals(){const btn=$("#apply-proposals");btn.disabled=true;btn.textContent="套用中…";$$('.creative-card').forEach(card=>card.classList.add("is-moving"));setTimeout(()=>{state.proposalsApplied=true;state.cards=clone(data.arenaCardsAfter);state.summary=data.summaryAfter;render();setTimeout(closeCoach,2000);},800);}
  function showToast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("is-visible");setTimeout(()=>t.classList.remove("is-visible"),1200);}
  function reset(){Object.assign(state,{view:"setup",setupStep:1,connected:{meta:false,google:false,tiktok:false},tracking:false,analysis:false,launched:false,proposalsApplied:false,creativeSet:"A",filter:"all",cards:clone(data.arenaCardsBefore),summary:data.summaryBefore,drawer:false});$("#product-prompt").value="賣手沖咖啡豆訂閱，主打新鮮烘焙";render();closeCoach();}
  document.addEventListener("click",e=>{const t=e.target.closest("button");if(!t)return;if(t.matches(".connect-button"))connectPlatform(t.dataset.platform);if(t.id==="detect-tracking")detectTracking();if(t.id==="to-strategy"){state.setupStep=2;render();}if(t.matches(".step-tab[data-step='1']")){state.setupStep=1;render();}if(t.matches(".step-tab[data-step='2']")&&state.analysis){state.setupStep=2;render();}if(t.id==="generate-analysis")generateAnalysis();if(t.id==="enter-arena"){state.view="arena";render();}if(t.id==="refresh-creatives")swapCreatives();if(t.matches(".filter-chip")){state.filter=t.dataset.filter;$$('.filter-chip').forEach(x=>x.classList.toggle("is-active",x===t));renderBoard();}if(t.id==="start-launch")openLaunch();if(t.id==="confirm-launch")confirmLaunch();if(t.id==="coach-trigger")openCoach();if(t.id==="close-coach"||t.id==="coach-backdrop")closeCoach();if(t.id==="apply-proposals")applyProposals();if(t.id==="reset-demo")reset();if(t.hasAttribute("data-close-modal"))$("#launch-modal").classList.add("is-hidden");});
  render();
})();
